1	//! Whole-second durations written as `90s`, `6m` or `1h`.
2	
3	use std::time::Duration;
4	
5	/// The longest duration a config value may name.
6	pub const MAX_DURATION: Duration = Duration::from_secs(3600);
7	
8	/// Parses `<digits><s|m|h>`; zero and anything over [`MAX_DURATION`] are rejected.
9	pub fn parse_duration(text: &str) -> Option<Duration> {
10	    let (digits, unit) = text.split_at(text.len().checked_sub(1)?);
11	    let seconds_per_unit = match unit {
12	        "s" => 1,
13	        "m" => 60,
14	        "h" => 3600,
15	        _ => return None,
16	    };
17	    if digits.is_empty() || !digits.bytes().all(|byte| byte.is_ascii_digit()) {
18	        return None;
19	    }
20	    let duration = Duration::from_secs(digits.parse::<u64>().ok()?.checked_mul(seconds_per_unit)?);
21	    (!duration.is_zero() && duration <= MAX_DURATION).then_some(duration)
22	}
23	
24	/// The shortest exact spelling: `6m` for 360 seconds, `90s` for 90.
25	pub fn render_duration(duration: Duration) -> String {
26	    let seconds = duration.as_secs();
27	    if seconds != 0 && seconds.is_multiple_of(3600) {
28	        format!("{}h", seconds / 3600)
29	    } else if seconds != 0 && seconds.is_multiple_of(60) {
30	        format!("{}m", seconds / 60)
31	    } else {
32	        format!("{seconds}s")
33	    }
34	}
