69	        for seconds in [1, 59, 60, 90, 120, 360, 3600] {
70	            let duration = Duration::from_secs(seconds);
71	            assert_eq!(parse_duration(&render_duration(duration)), Some(duration));
72	        }
73	        assert_eq!(render_duration(Duration::from_secs(360)), "6m");
74	        assert_eq!(render_duration(Duration::from_secs(90)), "90s");
75	    }
76	}
