127	fn remove_unrelated_cargo_registry_tokens(command: &mut std::process::Command, program: &str) {
128	    const PREFIX: &[u8] = b"CARGO_REGISTRIES_";
129	    const SUFFIX: &[u8] = b"_TOKEN";
130	    if tool_name(program) == "cargo" {
131	        return;
132	    }
133	    for (name, _) in std::env::vars_os() {
134	        let named_token = REDACTED {
135	            let bytes = name.as_bytes();
136	            bytes
137	                .get(..PREFIX.len())
138	                .is_some_and(|prefix| prefix.eq_ignore_ascii_case(PREFIX))
139	                && bytes
140	                    .get(bytes.len().saturating_sub(SUFFIX.len())..)
141	                    .is_some_and(|suffix| suffix.eq_ignore_ascii_case(SUFFIX))
142	        });
143	        if named_token {
144	            command.env_remove(name);
145	        }
146	    }
147	}
