396	/// Drains `reader` to its end and returns what it said, keeping at most [`MAX_CAPTURED_OUTPUT_BYTES`]; the rest is
397	/// read and dropped so the child never blocks on a full pipe.
398	///
399	/// With `echo`, each line is also written to this process's stderr with `secrets` redacted first (registry tools can
400	/// echo a credential verbatim). The returned text stays raw so classifiers keep matching exact upstream text. Lines
401	/// are read as bytes: a line iterator has no bound on a single line, so a flood with no newlines would buffer without
402	/// limit before it could be capped.
403	fn capture_stream(mut reader: impl Read, echo: bool, secrets: &[String]) -> String {
404	    let mut captured: Vec<u8> = Vec::new();
405	    let mut truncated = false;
406	    let mut pending_line: Vec<u8> = Vec::new();
407	    let mut chunk = [0u8; 65536];
408	    let echo_line = |line: &mut Vec<u8>| {
409	        if line.last() == Some(&b'\r') {
410	            line.pop();
411	        }
412	        eprintln!("{}", redact_known_secrets(&String::from_utf8_lossy(line), secrets));
413	    };
414	    loop {
415	        match reader.read(&mut chunk) {
416	            Ok(0) | Err(_) => break,
417	            Ok(n) => {
418	                let data = &chunk[..n];
419	                if echo {
420	                    for &b in data {
421	                        if b == b'\n' {
422	                            echo_line(&mut pending_line);
423	                            pending_line.clear();
424	                        } else if pending_line.len() < MAX_CAPTURED_OUTPUT_BYTES {
425	                            pending_line.push(b);
426	                        }
427	                    }
428	                }
429	                if !truncated {
430	                    let take = data.len().min(MAX_CAPTURED_OUTPUT_BYTES - captured.len());
431	                    captured.extend_from_slice(&data[..take]);
432	                    truncated = take < data.len();
433	                }
434	            }
435	        }
436	    }
437	    if echo && !pending_line.is_empty() {
438	        echo_line(&mut pending_line);
439	    }
440	    let mut text = String::from_utf8_lossy(&captured).into_owned();
441	    if truncated {
442	        text.push_str("\n...[output truncated]\n");
443	    }
444	    text
445	}
