453	/// `extract_retry_after_duration`, `detect_auth_failure`) can still match
454	/// exact upstream text. Callers pass the secrets list in rather than this
455	/// function reading the environment itself, keeping it pure and testable
456	/// with a synthetic list.
457	fn run_with_timeout_impl(
458	    program: &str,
459	    args: &[&str],
460	    cwd: &Path,
461	    timeout: Duration,
462	    echo: LiveEcho,
463	    live_secrets: Vec<String>,
464	    child_env: ChildEnvironment<'_>,
465	) -> Result<CommandOutput, CommandError> {
466	    let mut command = std::process::Command::new(program);
467	    command
468	        .args(args)
469	        .current_dir(cwd)
470	        .stdin(Stdio::null())
