51	/// The shipped impl. A thin, stateless adapter over
52	/// `crate::conventional::infer_severity` -- it holds no fields of its own; the caller's
53	/// [`GitAccess`] is handed in per call via [`SeverityInference::infer`]'s `git` parameter
54	/// rather than discovered here, so this type carries nothing to discover it with.
55	pub struct CommitInference;
56	
57	impl SeverityInference for CommitInference {
58	    fn infer(
59	        &self,
60	        pkg: &Package,
61	        git: &GitAccess<'_>,
62	        window: InferenceWindowSpec<'_>,
63	    ) -> Result<Option<InferenceOutcome>, GraphError> {
64	        use crate::conventional::{infer_severity, InferenceInput, InferenceWindow};
65	
66	        let inf_window = match window.since {
67	            Some(sha) => InferenceWindow::SinceCommit(sha),
68	            None => InferenceWindow::FullHistory,
69	        };
70	
71	        let input = InferenceInput {
72	            package: &pkg.id,
73	            pathspecs: window.pathspecs,
74	            window: inf_window,
75	            current_version: window.current_version,
76	            has_prior_release: window.has_prior_release,
77	        };
78	
79	        // Selecting the VCS backend is this layer's job: `conventional`
80	        // takes any `callisto_model::CommitWalker` and never names a VCS crate.
81	        let raw = infer_severity(git, &input)?;
82	        if raw.commit_count == 0 {
83	            return Ok(None);
84	        }
85	
86	        let (severity, remapped) = crate::aggregate::apply_pre_major(
87	            raw.severity,
88	            window.policy,
89	            window.current_version,
90	            window.has_prior_release,
91	        );
92	
93	        let commits = raw
94	            .commits
95	            .into_iter()
96	            .map(|c| (c.sha().clone(), c.subject().to_string()))
97	            .collect();
98	
99	        Ok(Some(InferenceOutcome {
100	            severity,
101	            commit_count: raw.commit_count,
102	            remapped,
103	            commits,
104	        }))
105	    }
106	}
